// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

interface ICALCULATOR {
    function add(uint a)external;
    function sub(uint a)external;
    function multi(uint a)external;
    function divide(uint a)external;
    function result()external view returns(uint);
    function clear()external;
}

contract calculator{
    ICALCULATOR public calc;

    constructor(address calculatorAddress){
        calc = ICALCULATOR(calculatorAddress);
    }

    function Cadd(uint a) public{
        calc.add(a);
    }
    function Csub(uint a) public{
        calc.sub(a);
    }
    function Cmulti(uint a) public{
        calc.multi(a);
    }
    function Cdivide(uint a) public{
        calc.divide(a);
    }
    function Cresult() public view returns(uint){
        return calc.result();
    }
    function Cclear() public{
        calc.clear();
    }
}

